
.readout {
  flex: 1 1 0;
  min-width: 0;
}

.head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px;
  margin-bottom: 4px;
}

.name {
  font-size: 12px;
  font-weight: 600;
}

.note {
  font-size: 11px;
  color: var(--c-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.gauge {
  display: flex;
  align-items: center;
  gap: 7px;
}

.track {
  position: relative;
  flex: 1 1 0;
  height: 7px;
  background-color: var(--c-track);
  border: 1px solid var(--c-border);
}

.fill {
  height: 100%;
  background-color: var(--c-accent);
  transition: width 0.5s ease;
}

.ticks {
  position: absolute;
  inset: 0;
}

.tick {
  position: absolute;
  top: 0;
  width: 1px;
  height: 100%;
  background-color: var(--c-surface);
  transition: opacity 0.4s ease;
}

.tick.gone {
  opacity: 0;
}

.value {
  min-width: 24px;
  text-align: right;
  font-size: 12px;
  font-weight: 700;
}
