
.panel {
  width: 100%;
  max-width: 640px;
  margin: 0 auto;
  border: 1px solid var(--c-border);
  background-color: var(--c-surface);
  box-shadow: 2px 2px 0 rgb(51 48 42 / 12%);
}

.readouts {
  display: flex;
  gap: 12px;
  padding: 9px 12px 8px;
  border-bottom: 1px solid var(--c-border);
}

.bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 5px 12px;
  border-bottom: 1px solid var(--c-border);
}

.badges {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.badge {
  padding: 1px 6px;
  font-size: 11px;
  color: var(--c-muted);
  border: 1px solid var(--c-border);
}

.badge.alert {
  color: var(--c-alert);
  border-color: var(--c-alert);
}

.toggle {
  flex: 0 0 auto;
  padding: 2px 10px;
  font-family: inherit;
  font-size: 11px;
  color: var(--c-text);
  cursor: pointer;
  background-color: var(--c-surface-sunken);
  border: 1px solid var(--c-border);

  &:hover {
    background-color: var(--c-track);
  }
}

.detail {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 9px 12px 11px;
}

.sub {
  padding-top: 2px;
}

.sub-note {
  margin-top: 5px;
  font-size: 11px;
  color: var(--c-muted);
}
