
.state {
  padding: 8px 9px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  gap: 5px;
}

.cell {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px;
  padding: 3px 7px;
  border: 1px solid var(--c-border);
  background-color: var(--c-surface);
}

.cell-name {
  font-size: 12px;
  font-weight: 600;
}

.cell-stage {
  font-size: 11px;
  color: var(--c-accent);
  white-space: nowrap;
}

.bodies {
  margin-top: 7px;
  padding-top: 6px;
  border-top: 1px dashed var(--c-border);
}

.body-row {
  display: flex;
  gap: 6px;
  padding: 2px 0;
  font-size: 11px;
}

.body-name {
  flex: 0 0 auto;
  color: var(--c-muted);
}

.body-text {
  flex: 1 1 auto;
}
