
.ledger {
  border: 1px solid var(--c-border);
  background-color: var(--c-surface);
}

.ledger-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding: 5px 9px;
  border-bottom: 1px solid var(--c-border);
  background-color: var(--c-surface-sunken);
}

.title {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.ratio {
  font-size: 11px;
  color: var(--c-muted);
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.ledger-body {
  padding: 3px 9px 6px;
}

/* 横线格：账本纸的观感 */
.ledger-row {
  display: flex;
  align-items: baseline;
  gap: 5px;
  padding: 3px 0;
  border-bottom: 1px dashed var(--c-border);

  &:last-child {
    border-bottom: none;
  }
}

.label {
  flex: 0 0 auto;
  font-size: 12px;
  color: var(--c-muted);
}

.dots {
  flex: 1 1 auto;
  height: 0;
  border-bottom: 1px dotted var(--c-border);
  transform: translateY(-3px);
}

.value {
  font-size: 13px;
  font-weight: 700;
}

.value.money {
  color: var(--c-money);
}

.unit {
  font-size: 11px;
  color: var(--c-muted);
}
