
.header {
  position: relative;
  padding: 10px 12px 9px;
  background-color: var(--c-surface-sunken);
  border-bottom: 1px solid var(--c-border);
  // 明线：瓷砖缝。公开度升高后由父级 .loud 换成墙面横纹
  background-image: linear-gradient(90deg, var(--c-border) 1px, transparent 1px);
  background-size: 28px 100%;
}

.header.loud {
  background-image: repeating-linear-gradient(
    to bottom,
    var(--c-border) 0px,
    var(--c-border) 1px,
    transparent 1px,
    transparent 6px
  );
  background-size: auto;
  border-bottom-color: var(--c-accent);
}

.row-main {
  display: flex;
  align-items: baseline;
  gap: 6px;
  font-size: 15px;
  font-weight: 700;
}

.origin {
  letter-spacing: 0.08em;
}

.sep {
  color: var(--c-muted);
  font-weight: 400;
}

.time {
  font-size: 13px;
  font-weight: 500;
  color: var(--c-muted);
}

.row-sub {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-top: 3px;
  font-size: 11px;
  color: var(--c-muted);
}

.progress {
  text-align: right;
}

.sign {
  position: absolute;
  right: 10px;
  top: 8px;
  padding: 1px 7px;
  font-size: 11px;
  color: var(--c-alert);
  border: 1px solid var(--c-alert);
  border-radius: 2px;
  transform: rotate(-3deg);
  background-color: var(--c-surface);
}
